'use strict';
const COMBAT_ANIMATION_MS=1700;
function combatGuide(c){if(!c.guided)return '';const reveal=c.phase==='reveal',die=c.hand.some(p=>p.die);const title=reveal?'4 · Read what happened':!c.hand.length?'1 · Choose your hand':!die?'2 · Add a die, if you want':'3 · Commit your hand';const text=reveal?`You took ${c.result.player.damage} damage; the boar took ${c.result.enemy.damage}. ${c.result.player.blocked?`Your Defense blocked ${c.result.player.blocked}. `:''}Both hands resolved together. Used cards lose one use, and attached dice are spent for the fight. ${c.result.outcome?'The encounter is over. Choose Finish encounter.':'Continue with a new hand.'}`:!c.hand.length?'Try Melee Strike and Defense together. There is no hand-size cap, but each card can appear only once in a round. The enemy’s hand is already locked and hidden.':!die?'Use “Attach die” below a selected card to try your luck, or commit without one. One die per card; three dice for the entire fight. Rolls stay hidden and may help or hurt.':'When you are ready, press “Commit hand”. Both sides reveal and act together. Defense reduces damage in that same round; it is not a reaction afterwards.';return `<aside class="encounter-guide" aria-label="Encounter guide"><strong>${title}</strong><p>${text}</p>${!reveal&&!c.hand.length&&c.round===1?'<button class="quiet" id="exampleRound">Show an example round →</button>':''}</aside>`}
function animateCombatRound(c){if(preferences.reduceMotion||reducedMotion?.matches)return;const panel=c.guided?$('guidedCombat'):$('modalContent'),button=$('commitHand'),label=button.textContent;panel.classList.add('battle-playing');panel.setAttribute('aria-busy','true');button.disabled=true;button.textContent='Resolving both hands…';$('animationStatus').textContent='Both hands committed. Watch the encounter resolve.';setTimeout(()=>{if(combat!==c||c.phase!=='reveal')return;panel.classList.remove('battle-playing');panel.setAttribute('aria-busy','false');$('commitHand').disabled=false;$('commitHand').textContent=label;$('animationStatus').textContent='Round resolved. Damage and remaining uses are shown below.'},COMBAT_ANIMATION_MS)}
function showEncounterWalkthrough(){combat=null;const preview={guided:true,practice:true,round:1,phase:'choose',place:{enemyType:'boar'},player:battleFighter(state.character.name,CFG.maxHP,maxMana(),[]),enemy:battleEnemy('boar')};$('modal').classList.add('battle-dialog');showCombatSurface(`${combatScene(preview).replace('Choose your cards. Your opponent has already committed.','A wild boar blocks the trail. What will you do?').replace('Choose your hand. Both fighters hold their ground.','A wild boar blocks the trail. What will you do?').replace('Hand hidden','Alert').replace('</section>','<div class="encounter-speech">The boar snorts, lowers its tusks, and blocks your way.</div></section>')}<div class="encounter-intro"><div class="eyebrow">A GUIDED ENCOUNTER · 01 / MEET</div><h2>A rustle beyond the trail.</h2><p>You leave the safe yellow path outside Hearthstead. A wild boar steps out of the trees. Approaching it starts an encounter; the fight begins only when you choose to stand your ground.</p><div class="guided-choice">In your world, walk next to an enemy and press E or tap Interact. Its speech appears over its head. Roads are safer than the forest, and your village is safe.</div><div class="actions">${actionButton('Stand your ground →','beginGuided')}${actionButton('Back away','leaveGuided','quiet')}</div><p>Practice only. Your health, items and progress will stay as they are.</p></div>`,true);$('beginGuided').onclick=()=>{startCombat({name:'Forest edge',enemyType:'boar',practice:true,guided:true,encounter:true});combat.player.hp=combat.player.maxHP;combat.player.mana=maxMana();renderCombat()};$('leaveGuided').onclick=leavePractice}
// Combat UI shared by world encounters and the isolated review arena.
function playerBattleCards(){const p=state.character.pillars;return [
 battleCard('melee','Melee Strike','attack',LIFE.meleeBase+p.might*LIFE.meleePerMight,BATTLE.meleeUses),
 battleCard('guard','Defense','defense',BATTLE.defenseBase+p.resilience*BATTLE.defensePerResilience,BATTLE.defenseUses),
 battleCard('bolt','Arcane Bolt','attack',13+p.arcane*2,BATTLE.spellUses,{mana:5}),
 battleCard('wind','Second Wind','heal',20,BATTLE.healUses),
 ...state.ownedCards.map(id=>{const g=GOODS.find(g=>g.id===id);return battleCard(id,g.name,g.damage?'attack':'heal',g.damage||g.healCard,3,{mana:g.mana})}),
 ...(combat?.practice?[battleCard('ember','Ember Seal','attack',22,1,{consumable:true})]:[])
]}
function startCombat(place){
 combat={place,guided:!!place.guided,practice:!!place.practice,round:1,phase:'choose',hand:[],history:[],fleeAttempts:0,negotiated:false};
 combat.player=battleFighter(state.character.name,CFG.maxHP,state.mana,playerBattleCards());combat.player.hp=state.hp;
 combat.enemy=battleEnemy(place.enemyType);combat.enemy.name=place.enemy||combat.enemy.name;
 // Commit before the player selects anything. Re-rendering never changes this hand.
 combat.enemyHand=battleChoose(combat.enemy,random);renderCombat();(combat.guided?$('guidedCombat'):$('modal')).scrollTop=0;
}
function battleSummary(result){return `${result.damage} damage taken · ${result.blocked} blocked${result.healed?' · '+result.healed+' healed':''}${result.dodged?' · dodged '+result.dodged:''}`}
function renderCombat(){const c=combat,p=c.player,e=c.enemy,reveal=c.phase==='reveal',spent=c.hand.filter(x=>x.die).length;
 const host=c.guided?$('guidedCombat'):$('modalContent'),trayScroll=host.querySelector('.battle-cards')?.scrollLeft||0;if(!c.guided)$('modal').classList.add('battle-dialog');host.classList.remove('battle-playing');host.setAttribute('aria-busy','false');
 showCombatSurface(`${combatScene(c)}<div class="combat-command">${combatGuide(c)}<div class="battle-header"><div class="eyebrow">${reveal?'ROUND RESOLVED':'YOUR BUSTAGAM'}</div><span>${reveal?'Both hands revealed':'Select cards, then commit together'}</span></div>
 ${reveal?`<div class="battle-reveal" role="status"><p><b>You played</b> ${c.result.playerCards.join(', ')||'Pass'}</p><p><b>Opponent played</b> ${c.result.enemyCards.join(', ')||'Pass'}</p><div class="battle-results"><p>You: ${battleSummary(c.result.player)}</p><p>Opponent: ${battleSummary(c.result.enemy)}</p></div></div>`:'<p class="battle-hint">Select any available cards. Attach up to one die per card. Both hands resolve together; dice can strengthen or weaken an effect.</p>'}
 <div class="battle-cards">${p.cards.map(card=>{const pick=c.hand.find(x=>x.id===card.id),disabled=reveal||card.uses<=0;return `<article class="battle-card kind-${card.kind} ${pick?'selected':''} ${card.uses<=0?'exhausted':''}"><button data-pick="${card.id}" aria-pressed="${!!pick}" ${disabled?'disabled':''}><span class="card-kind">${card.kind.toUpperCase()}</span><span class="card-art" aria-hidden="true">${card.kind==='defense'?'⬡':card.kind==='heal'?'✺':card.id==='melee'?'⚔':'ϟ'}</span><strong>${card.name}</strong><span class="card-power">${card.power} <small>${card.kind==='attack'?'damage':card.kind==='defense'?'block':'healing'}</small></span><small>${card.mana?card.mana+' mana · ':''}${card.consumable?'Consumed forever':'Resets next fight'}</small><b class="card-uses">${card.uses} uses left ${pick?'· Selected':''}</b></button><button class="attach-die" data-die="${card.id}" aria-pressed="${!!pick?.die}" ${disabled||!pick||(!pick.die&&spent>=p.dice)?'disabled':''}>${pick?.die?'✦ Die attached':'＋ Attach die'}</button></article>`}).join('')}</div>
 <div class="battle-footer"><span>${reveal?'✦ marks an attached die. Roll values stay hidden.':`${c.hand.length} cards selected · ${spent} dice attached`}</span><button class="primary" id="commitHand">${reveal?(c.result.outcome?'Finish encounter':'Next round →'):(c.hand.length?'Commit hand →':'Pass this round →')}</button></div>
 ${!reveal?`<div class="battle-secondary"><button class="quiet" id="battleFlee" ${c.fleeAttempts>=BATTLE.fleeAttempts?'disabled':''}>Flee (${BATTLE.fleeAttempts-c.fleeAttempts} attempts)</button><button class="quiet" id="battleTalk" ${c.negotiated?'disabled':''}>Negotiate (${c.negotiated?0:1} attempt)</button>${c.practice?'<button class="quiet" id="exitPractice">Leave practice</button>':'<button class="quiet" id="surrenderBattle">Surrender</button>'}</div>`:''}
 <div id="animationStatus" class="animation-status" role="status" aria-live="polite"></div><details class="battle-history"><summary>Round history · ${c.history.length}</summary>${c.history.map(x=>`<p>${escapeText(x)}</p>`).join('')||'<p>No rounds resolved yet.</p>'}</details></div>`,c.guided);
 const cardTray=host.querySelector('.battle-cards');if(cardTray)cardTray.scrollLeft=trayScroll;if(!c.guided)$('modalContent').querySelector('.close').hidden=true;
 document.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{const i=c.hand.findIndex(x=>x.id===b.dataset.pick);if(i>=0)c.hand.splice(i,1);else c.hand.push({id:b.dataset.pick,die:false});renderCombat()});
 document.querySelectorAll('[data-die]').forEach(b=>b.onclick=()=>{const pick=c.hand.find(x=>x.id===b.dataset.die);if(pick)pick.die=!pick.die;renderCombat()});
 $('commitHand').onclick=()=>reveal?nextBattleRound():commitBattleHand();if(c.guided&&!reveal&&!c.hand.length&&c.round===1)$('exampleRound').onclick=()=>{c.hand=[{id:'melee',die:true},{id:'guard',die:false}];commitBattleHand()};
 if(!reveal){$('battleFlee').onclick=()=>battleAlternative('flee');$('battleTalk').onclick=()=>battleAlternative('talk');if(c.practice)$('exitPractice').onclick=leavePractice;else $('surrenderBattle').onclick=()=>{state.hp=0;finishTurn()}}
}
function commitBattleHand(){const c=combat;if(!c||c.phase!=='choose')return;if(!battleValid(c.player,c.hand)){notify('Your selected hand needs more mana or dice.');return}
 c.beforeHP={player:c.player.hp,enemy:c.enemy.hp};c.result=battleResolve(c.player,c.enemy,c.hand,c.enemyHand,random);c.phase='reveal';
 c.history.unshift((c.actionFailure||'')+`Round ${c.round}: You played ${c.result.playerCards.join(', ')||'Pass'}; opponent played ${c.result.enemyCards.join(', ')||'Pass'}. You took ${c.result.player.damage}; opponent took ${c.result.enemy.damage}.`);
 if(!c.practice){state.hp=c.player.hp;state.mana=c.player.mana;save();updateUI()}renderCombat();(c.guided?$('guidedCombat'):$('modal')).scrollTop=0;animateCombatRound(c);
}
function nextBattleRound(){const c=combat;if(c.result.outcome){if(c.practice){showPracticeResult(c.result.outcome);return}$('modal').classList.remove('battle-dialog');if(c.result.outcome==='victory')victory('Both hands resolve. The guardian falls.');else finishTurn();return}c.round++;c.hand=[];c.actionFailure='';c.phase='choose';c.enemyHand=battleChoose(c.enemy,random);renderCombat();$('modal').scrollTop=0}
function battleAlternative(kind){const c=combat,p=state.character.pillars;let success=false;
 if(kind==='flee'){if(c.fleeAttempts>=BATTLE.fleeAttempts)return;c.fleeAttempts++;success=random()<Math.min(.85,BATTLE.fleeBase+p.instinct*BATTLE.fleePerInstinct)}else{if(c.negotiated)return;c.negotiated=true;success=random()<Math.min(.75,BATTLE.negotiateBase+(p.influence+p.wit)*BATTLE.negotiatePerPillar)}
 if(success){if(c.practice){showPracticeResult(kind==='flee'?'escaped':'negotiated');return}$('modal').classList.remove('battle-dialog');if(kind==='talk')victory('You find a peaceful way forward.');else{closeModal();goHome(false);notify('You escape to Hearthstead.')}return}
 c.actionFailure=kind==='flee'?'Escape failed. ':'Negotiation refused. ';c.hand=[];commitBattleHand();
}
function finishTurn(){updateUI();save();if(state.hp<=0){const protectedByVault=state.vaults>0;if(protectedByVault)state.vaults--;else state.xp=Math.max(0,state.xp-20);combat=null;$('modal').classList.remove('battle-dialog');goHome(true);showModal(`<div class="eyebrow">THE HEARTH CALLS YOU BACK</div><h2>${protectedByVault?'Your Vault holds.':'A new beginning.'}</h2><p>${protectedByVault?'Your Vault Card is consumed, protecting your progress.':'You return home, losing up to 20 XP.'} Rest and try again.</p>${actionButton('Rise again','rise')}`);$('rise').onclick=closeModal}else renderCombat()}
function combatPracticeMenu(){showModal(`<div class="eyebrow">COMBAT LAB · REVIEW PROTOTYPE</div><h2>Choose an opponent.</h2><button class="primary" id="guidedEncounter">Play a guided encounter →</button><p>Practice uses a fresh copy of your health and cards. Your journey stays as it is. The Ember Seal is a practice-only consumable.</p><div class="practice-opponents">${Object.entries(BATTLE.enemies).map(([id,e])=>`<button class="quiet" data-practice="${id}"><strong>${e.name}</strong><small>${e.hp} HP · ${e.attack} attack · ${id==='bear'?'Dodge ×2':'Defense ×5'}</small></button>`).join('')}</div>`);$('guidedEncounter').onclick=showEncounterWalkthrough;document.querySelectorAll('[data-practice]').forEach(b=>b.onclick=()=>{startCombat({name:'Combat Lab',enemyType:b.dataset.practice,practice:true,encounter:true});combat.player.hp=combat.player.maxHP;combat.player.mana=maxMana();renderCombat()})}
function leavePractice(){closeGuidedSurface();combat=null;$('modal').classList.remove('battle-dialog');closeModal();mainMenu()}
function showPracticeResult(outcome){if(combat?.guided){renderGuidedOutcome(combat,outcome);return}combat=null;$('modal').classList.remove('battle-dialog');showModal(`<div class="eyebrow">PRACTICE COMPLETE</div><h2>${{victory:'Victory.',defeat:'Defeated.',draw:'Both fighters fall.',escaped:'You escaped.',negotiated:'A peaceful ending.'}[outcome]}</h2><p>No progress or items changed. Try a different hand or opponent.</p><div class="actions">${actionButton('Try another fight','retryPractice')}${actionButton('Main menu','leaveLab','quiet')}</div>`);$('retryPractice').onclick=combatPracticeMenu;$('leaveLab').onclick=leavePractice}
